CREATE TABLE IF NOT EXISTS contract_variations (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,variation_code VARCHAR(30) NOT NULL,client_contract_id BIGINT UNSIGNED NOT NULL,variation_number VARCHAR(50) NULL,variation_type VARCHAR(30) NOT NULL,title VARCHAR(190) NOT NULL,description TEXT NULL,variation_date DATE NOT NULL,effective_date DATE NULL,amount DECIMAL(18,2) NULL,amount_effect VARCHAR(20) NOT NULL,markup_percentage DECIMAL(7,4) NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',notes TEXT NULL,approved_at DATETIME NULL,approved_by BIGINT UNSIGNED NULL,cancelled_at DATETIME NULL,cancelled_by BIGINT UNSIGNED NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_contract_variations_code(variation_code),UNIQUE KEY uq_contract_variations_number(client_contract_id,variation_number),KEY idx_contract_variations_contract_status(client_contract_id,status),KEY idx_contract_variations_date(variation_date),KEY idx_contract_variations_approved_by(approved_by),KEY idx_contract_variations_cancelled_by(cancelled_by),CONSTRAINT fk_contract_variations_contract FOREIGN KEY(client_contract_id) REFERENCES client_contracts(id) ON DELETE RESTRICT,CONSTRAINT fk_contract_variations_approved_by FOREIGN KEY(approved_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_contract_variations_cancelled_by FOREIGN KEY(cancelled_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT chk_contract_variations_type CHECK(variation_type IN('addendum','additional_work','deduction','commercial_adjustment')),CONSTRAINT chk_contract_variations_effect CHECK(amount_effect IN('increase','decrease','none')),CONSTRAINT chk_contract_variations_status CHECK(status IN('draft','approved','cancelled')),CONSTRAINT chk_contract_variations_amount CHECK(amount IS NULL OR amount>=0),CONSTRAINT chk_contract_variations_markup CHECK(markup_percentage IS NULL OR markup_percentage>0),CONSTRAINT chk_contract_variations_effect_values CHECK((amount_effect='none' AND amount IS NULL AND markup_percentage IS NULL) OR (amount_effect IN('increase','decrease') AND amount IS NOT NULL)),CONSTRAINT chk_contract_variations_type_effect CHECK((variation_type='addendum') OR (variation_type='additional_work' AND amount_effect='increase') OR (variation_type='deduction' AND amount_effect='decrease') OR (variation_type='commercial_adjustment' AND amount_effect IN('increase','decrease')))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
